22|/**
23| * Resolve an eMAG client for a request. Prefers per-request credential
24| * headers (X-Emag-Username, X-Emag-Password, X-Emag-Platform) sent by
25| * node_api's ConnectionJobScheduler. Falls back to the singleton client
26| * for backward compatibility.
27| */
28|export const getClientForRequest = (req: Request): Emag => {
29|  const username = req.headers['x-emag-username'] as string | undefined;
30|  const password = req.headers['x-emag-password'] as string | undefined;
31|  const platform = (req.headers['x-emag-platform'] as Platform) || 'ro';
32|
33|  if (username && password) {
34|    return new Emag(username, password, platform);
35|  }
36|
37|  return requireEmagClient();
