24|export const formatEmagError = (error: any): { message: string; details?: any } => {
25|  if (axios.isAxiosError(error)) {
26|    const axiosError = error as AxiosError<any>;
27|    if (axiosError.response) {
28|      const { status, data } = axiosError.response;
29|      if (data?.isError && data?.messages?.length > 0) {
30|        return {
31|          message: data.messages.join(', '),
32|          details: data,
33|        };
34|      }
35|      if (data?.message) {
36|        return { message: data.message, details: data };
37|      }
38|      return {
39|        message: `HTTP ${status}: ${axiosError.message}`,
40|        details: data,
41|      };
42|    }
43|    return { message: axiosError.message };
44|  }
45|  return {
46|    message: error.message || 'Unknown error occurred',
47|    details: error,
48|  };
49|};

44|  }
45|  return {
46|    message: error.message || 'Unknown error occurred',
47|    details: error,
48|  };
