51|export const errorHandler = (
52|  err: Error | ApiError,
53|  req: Request,
54|  res: Response,
55|  next: NextFunction
56|) => {
57|  console.error(`[ERROR] ${req.method} ${req.path}:`, err);
58|
59|  let statusCode = 500;
60|  let message = 'An unexpected error occurred';
61|  let details: any = undefined;
62|
63|  if (err instanceof ApiError) {
64|    statusCode = err.statusCode;
65|    message = err.message;
66|    details = err.details;
67|  } else if (axios.isAxiosError(err)) {
68|    const formatted = formatEmagError(err);
69|    statusCode = err.response?.status || 500;
70|    message = formatted.message;
71|    details = formatted.details;
72|  } else if (err instanceof Error) {
73|    message = err.message;
74|  }
75|
76|  res.status(statusCode).json({
77|    success: false,
78|    error: message,
79|    errorType: err.name || 'Error',
80|    message,
81|    details,
82|    timestamp: new Date().toISOString(),
83|    path: req.path,
84|    method: req.method,
85|  });
86|};
