1|/**
 2| * Internal API Key Authentication Middleware
 3| *
 4| * Validates that incoming requests carry a shared secret in the
 5| * X-Internal-API-Key header. This is a defense-in-depth measure:
 6| * the eMAG service should only be reachable via Docker networking,
 7| * but this middleware ensures even direct access is blocked without the key.
 8| */
 9|
10|import { Request, Response, NextFunction } from 'express';
11|
12|const INTERNAL_API_KEY = process.env.INTERNAL_API_KEY || '';
13|
14|export const requireInternalApiKey = (req: Request, res: Response, next: NextFunction): void => {
15|  if (!INTERNAL_API_KEY) {
16|    console.warn('[InternalAuth] INTERNAL_API_KEY not set — rejecting all requests. Set it in the environment.');
17|    res.status(503).json({
18|      success: false,
19|      error: 'Service not configured (missing internal API key)',
20|    });
21|    return;
22|  }
23|
24|  const provided = req.headers['x-internal-api-key'] as string | undefined;
25|
26|  if (!provided || provided !== INTERNAL_API_KEY) {
27|    res.status(401).json({
28|      success: false,
29|      error: 'Unauthorized — invalid or missing internal API key',
30|    });
31|    return;
32|  }
33|
34|  next();
35|};
