 85|  private getHeaders(contentType: string = 'application/json'): Record<string, string> {
 86|    return {
 87|      Authorization: `Basic ${this.token}`,
 88|      'Content-Type': contentType,
 89|      'Accept-Encoding': 'gzip, deflate, br',
 90|    };
 91|  }
 92|
 93|  async request<T>(
 94|    method: Method,
 95|    endpoint: string,
 96|    data?: any,
 97|    params?: Record<string, any>,
 98|    contentType?: string
 99|  ): Promise<T> {
100|    if (isDemoMode()) {
101|      return getDemoResponse(method, endpoint) as T;
102|    }
103|
104|    const url = `${this.config.baseUrl}${endpoint}`;
105|
106|    const config: AxiosRequestConfig = {
107|      method,
108|      url,
109|      headers: this.getHeaders(contentType),
110|      maxBodyLength: 10 * 1024 * 1024,
111|      maxRedirects: 0,
112|      timeout: 30000,
113|    };
114|
115|    if (data) {
116|      config.data = data;
117|    }
118|
119|    if (params) {
120|      config.params = params;
121|    }
122|
123|    try {
124|      const response: AxiosResponse<T> = await axios(config);
125|      return response.data;
126|    } catch (error: any) {
127|      throw error;
128|    }
129|  }
